import { useEffect, useState, type RefObject } from 'react'
import { isRTL } from '@/lib/direction'

export type FadeClass = '' | 'tab-bar-fade-left' | 'tab-bar-fade-right' | 'tab-bar-fade-both'

/**
 * Tracks whether the given scroll container has overflow content to the
 * left, right, both, or neither. Returns the CSS class name to apply.
 *
 * Listens to scroll on the container, plus resize (window + ResizeObserver
 * on the container) so the class updates when the container size or its
 * children change.
 *
 * `changeKey` is an optional value that, when it changes, forces the
 * effect to re-run. Use this when the scroll container element is
 * conditionally rendered by a parent (e.g., `{tabs.length >= 2 && <div ref={ref}>}`):
 * pass `tabs.length` (or any signal that the container has now mounted)
 * so the hook can attach its observers once the ref points at a real
 * element.
 */
export function useTabBarFade(ref: RefObject<HTMLElement | null>, changeKey?: unknown): FadeClass {
  const [fade, setFade] = useState<FadeClass>('')

  useEffect(() => {
    const el = ref.current
    if (!el) return

    const update = () => {
      const { scrollLeft, scrollWidth, clientWidth } = el
      const maxScroll = scrollWidth - clientWidth
      // Normalize across the LTR (0..max) and modern-RTL (0..-max) scrollLeft
      // conventions: `pos` is 0 at the START edge and grows toward the END.
      const pos = Math.abs(scrollLeft)
      // 1px tolerance handles sub-pixel rendering at the extreme edges.
      const canStart = pos > 1
      const canEnd = pos < maxScroll - 1
      // Map the logical start/end to the physical mask class per direction: the
      // start edge is on the left in LTR, on the right in RTL.
      const rtl = isRTL(el)
      const startClass: FadeClass = rtl ? 'tab-bar-fade-right' : 'tab-bar-fade-left'
      const endClass: FadeClass = rtl ? 'tab-bar-fade-left' : 'tab-bar-fade-right'
      const cls: FadeClass =
        canStart && canEnd ? 'tab-bar-fade-both'
          : canStart ? startClass
          : canEnd ? endClass
          : ''
      setFade(prev => prev === cls ? prev : cls)
    }

    update()
    el.addEventListener('scroll', update, { passive: true })
    const ro = new ResizeObserver(update)
    ro.observe(el)
    // Also observe each child -- a scrollable container's own size doesn't
    // change when overflow children are added, but ResizeObserver on the
    // children catches their sizing (e.g., async-loaded tab labels).
    Array.from(el.children).forEach(child => ro.observe(child))
    // MutationObserver catches add/remove of tab elements (e.g., when the
    // data snapshot arrives and renders the tabs).
    const mo = new MutationObserver(() => {
      Array.from(el.children).forEach(child => ro.observe(child))
      update()
    })
    mo.observe(el, { childList: true })
    window.addEventListener('resize', update)

    return () => {
      el.removeEventListener('scroll', update)
      ro.disconnect()
      mo.disconnect()
      window.removeEventListener('resize', update)
    }
  }, [ref, changeKey])

  return fade
}
